import React from 'react';
import DashboardChart from './DashboardChart';

const Dashboard = ({ properties, clients }) => {
  const totalProperties = properties.length;
  const totalClients = clients.length;
  const forSale = properties.filter(p => p.status === 'للبيع').length;
  const forRent = properties.filter(p => p.status === 'للإيجار').length;
  
  // Calculate average price safely
  const totalValue = properties.reduce((acc, curr) => acc + (Number(curr.price) || 0), 0);
  const avgPrice = totalProperties > 0 ? totalValue / totalProperties : 0;

  // Group by type
  const typeCounts = properties.reduce((acc, curr) => {
    const t = curr.type || 'غير محدد';
    acc[t] = (acc[t] || 0) + 1;
    return acc;
  }, {});

  // Data for the new chart
  const propertiesByCity = properties.reduce((acc, curr) => {
    const city = curr.location?.city || 'غير محدد';
    acc[city] = (acc[city] || 0) + 1;
    return acc;
  }, {});

  const chartData = Object.entries(propertiesByCity).map(([label, value]) => ({ label, value })).sort((a, b) => b.value - a.value).slice(0, 5);

  return (
    <div className="container fade-in">
      <h2 className="mb-4">📊 لوحة المعلومات</h2>
      
      <div className="row mb-4">
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-primary shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">إجمالي العقارات</h5>
              <p className="card-text display-4">{totalProperties}</p>
            </div>
          </div>
        </div>
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-success shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">إجمالي العملاء</h5>
              <p className="card-text display-4">{totalClients}</p>
            </div>
          </div>
        </div>
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-info shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">للعرض / للإيجار</h5>
              <p className="card-text display-6">{forSale} / {forRent}</p>
            </div>
          </div>
        </div>
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-warning shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">متوسط الأسعار</h5>
              <p className="card-text fs-4">{avgPrice.toLocaleString(undefined, { maximumFractionDigits: 0 })} ج</p>
            </div>
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-4 mb-4">
          <div className="card shadow-sm h-100">
            <div className="card-header bg-light fw-bold">توزيع أنواع العقارات</div>
            <div className="card-body">
              {Object.keys(typeCounts).length > 0 ? (
                <ul className="list-group list-group-flush">
                  {Object.entries(typeCounts).map(([type, count]) => (
                    <li key={type} className="list-group-item d-flex justify-content-between align-items-center">
                      {type}
                      <span className="badge bg-primary rounded-pill">{count}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-muted text-center py-4">لا توجد بيانات كافية</p>
              )}
            </div>
          </div>
        </div>
        
        <div className="col-md-8 mb-4">
          <div className="card shadow-sm h-100">
            <div className="card-header bg-light fw-bold">أحدث العقارات المضافة</div>
            <div className="card-body p-0">
              <ul className="list-group list-group-flush">
                {properties.slice(-5).reverse().map(p => (
                  <li key={p.id} className="list-group-item">
                    <div className="d-flex justify-content-between align-items-center">
                      <div>
                        <span className="fw-bold">{p.type}</span> <small className="text-muted">في {p.location?.city}</small>
                      </div>
                      <span className="text-success fw-bold">{Number(p.price)?.toLocaleString()} ج</span>
                    </div>
                  </li>
                ))}
                {properties.length === 0 && <li className="list-group-item text-center py-4">لا توجد عقارات</li>}
              </ul>
            </div>
          </div>
        </div>
        
        <div className="col-12 mb-4">
            <DashboardChart data={chartData} title="📊 عدد العقارات حسب المدينة (أعلى 5)" />
        </div>

        <div className="col-12 mb-4">
          <div className="card shadow-sm">
            <div className="card-header bg-white fw-bold border-bottom-0">📢 نشاطات السوق الأخيرة</div>
            <div className="card-body">
              <div className="d-flex align-items-center mb-3">
                <div className="bg-light rounded-circle p-2 me-3">🏠</div>
                <div>تم إضافة <strong>3 عقارات جديدة</strong> في منطقة المعادي اليوم.</div>
                <small className="ms-auto text-muted">منذ ساعتين</small>
